import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import data from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ImageModal, { type ImageItem } from "../components/ImageModal";
import Ornament from "../components/ornament";
import SEO from "../components/seo";

const userData: UserProfile = data;

const floorPlans = [
  {
    id: "plan-a",
    icon: "/plans/plan_A-Line.png",
    titleKey: "plans.a-line",
    files: ["plan_A-Line.png"],
  },
  {
    id: "plan-b",
    icon: "/plans/plan_B-Line.png",
    titleKey: "plans.b-line",
    files: ["plan_B-Line.png"],
  },
  {
    id: "plan-c",
    icon: "/plans/plan_C-Line.png",
    titleKey: "plans.c-line",
    files: ["plan_C-Line.png"],
  },
  {
    id: "plan-d",
    icon: "/plans/plan_D-Line.png",
    titleKey: "plans.d-line",
    files: ["plan_D-Line.png"],
  },
  {
    id: "plan-e",
    icon: "/plans/plan_E-Line.png",
    titleKey: "plans.e-line",
    files: ["plan_E-Line.png"],
  },
  {
    id: "plan-f",
    icon: "/plans/plan_F-Line.png",
    titleKey: "plans.f-line",
    files: ["plan_F-Line.png"],
  },
  {
    id: "plan-g",
    icon: "/plans/plan_G-Line.png",
    titleKey: "plans.g-line",
    files: ["plan_G-Line.png"],
  },
  {
    id: "plan-h",
    icon: "/plans/plan_H-Line.png",
    titleKey: "plans.h-line",
    files: ["plan_H-Line.png"],
  }
];

const PlansPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const [modalImages, setModalImages] = React.useState<ImageItem[]>([]);
  const [pendingOpen, setPendingOpen] = React.useState(false);
  const openModalRef = React.useRef<((startIndex?: number) => void) | null>(
    null
  );

  const openGallery = (images: ImageItem[]) => {
    setModalImages(images);
    setPendingOpen(true);
  };

  React.useEffect(() => {
    if (!pendingOpen || modalImages.length === 0) return;
    if (!openModalRef.current) return;
    openModalRef.current(0);
    setPendingOpen(false);
  }, [pendingOpen, modalImages]);

  const galleries = floorPlans.map((collection) => {
    const label = t(collection.titleKey) as string;
    const images = collection.files.map((file, index) => ({
      src: encodeURI(`/plans/${file}`),
      alt: `${label} ${index + 1}`,
      caption: label,
    }));

    return { ...collection, label, images };
  });

  return (
    <Layout data={userData}>
      <SEO
        data={userData}
        titleKey="plans.metaTitle"
        descriptionKey="plans.metaDescription"
        pathname="/plans/"
        schemaType="ProfessionalService"
      />
      <section>
        <ImageModal
          images={modalImages}
          trigger={(open) => {
            openModalRef.current = open;
            return null;
          }}
        />

        <section className="text-terracota bg-beige px-12 py-6 mb-6 shadow-lg">
          <h2 className={styles.title}>{t("menu.plans")}</h2>
          <p>{t("plans.heroContent")}</p>
          <img src="/historic/brochure/2502980008-pi.jpg" alt="Complete Floor Plan" className="w-3/4 mx-auto my-6" />
          <p className="w-3/4 mx-auto pt-6">{t("plans.plans")}</p>
        <article className="grid gap-1 md:grid-cols-4 w-3/4 mx-auto my-6">
          {galleries.map((gallery, index) => (
            <button
              key={gallery.id}
              type="button"
              className={`group text-terracota flex w-full flex-col items-center px-6 py-4 text-center transition duration-200 hover:-translate-y-1 `}
              onClick={() => openGallery(gallery.images)}
            >
              <img
                src={gallery.icon}
                alt={gallery.label}
                className="mb-0 h-28 w-auto object-contain"
              />
              <span className="body_mobile sm:body_desk">{gallery.label}</span>
            </button>
          ))}
        </article>



          <figure className="flex justify-center">
            <Ornament className="w-96 text-terracota/60 rotate-180" />
          </figure>
        </section>

      </section>
    </Layout>
  );
};

export default PlansPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  title: "h2_mobile sm:h2_desk text-center mb-6",
};
